import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import type { AppState } from '../contracts/index.ts'
import { courseBundle } from '../content/catalog.ts'
import { lessonOneBundle } from '../content/lesson-one.ts'
import { lessonTwoBundle } from '../content/lesson-two.ts'
import { createInitialState, currentTask, transition } from '../learning/engine.ts'
import { loadState, migrateState, StorageError, validateState } from './index.ts'
import { indexedDBModel } from './test-idb.ts'

// Generated by the real pre-addition engine, before lesson two entered the registry.
const baseline: AppState = JSON.parse(readFileSync(new URL('./fixtures/pre-lesson-two-schema5.json', import.meta.url), 'utf8'))
const NOW = '2026-11-09T10:00:00.000Z'

test('adding lesson two reads the complete pre-addition schema-five snapshot without migration or lost evidence', async () => {
  assert.equal(courseBundle.contentVersion, 'nuovo-espresso-a1-it-v1')
  assert.equal(baseline.contentVersion, courseBundle.contentVersion)
  assert.equal(baseline.schemaVersion, 5)
  assert.equal(lessonOneBundle.entries.length, 85)
  assert.ok(baseline.attempts.length > 0 && baseline.reverseReviews.length > 0)
  assert.ok(baseline.session!.draft.length > 0 && Object.keys(baseline.dailyActivity).length > 0)
  assert.ok(courseBundle.lessons!.some(lesson => lesson.lessonId === 'it-a1-lesson-02'))
  validateState(baseline, courseBundle)
  const original = structuredClone(baseline)
  const restored = migrateState(baseline, courseBundle)
  assert.notEqual(restored, baseline)
  assert.deepEqual(restored, original, 'every field, not just counters, survives the additive catalog')
  assert.deepEqual(baseline, original, 'the supplied snapshot is never normalized in place')

  const model = indexedDBModel(baseline), previous = globalThis.indexedDB
  globalThis.indexedDB = model.factory
  try {
    model.failNextPut()
    assert.deepEqual(await loadState(courseBundle), original, 'a current-version load needs no write or migration')
    assert.deepEqual(await loadState(courseBundle), original, 'a second load remains idempotent')
    assert.deepEqual(model.read(), original)
    assert.deepEqual(model.keys(), ['current'])
  } finally { globalThis.indexedDB = previous }
})

test('selecting and introducing lesson two preserves the old lesson session and does not duplicate its progress', () => {
  const firstId = lessonOneBundle.lesson.lessonId, secondId = lessonTwoBundle.lesson.lessonId
  const original = structuredClone(baseline)
  let state = migrateState(baseline, courseBundle)
  state = transition(state, { type: 'select-lesson', lessonId: secondId }, courseBundle, NOW)
  validateState(state, courseBundle)
  assert.deepEqual(state.savedSessions[firstId], original.session)
  assert.deepEqual(state.progress, original.progress)
  assert.deepEqual(state.attempts, original.attempts)
  assert.deepEqual(state.reverseReviews, original.reverseReviews)
  assert.deepEqual(state.dailyActivity, original.dailyActivity)
  state = transition(state, { type: 'start-session', sessionId: 'after-addition-second', seed: 197 }, courseBundle, NOW)
  validateState(state, courseBundle)
  assert.equal(state.session!.lessonId, secondId)
  for (const [id, progress] of Object.entries(original.progress)) assert.deepEqual(state.progress[id], progress)
  const newlyIntroduced = Object.keys(state.progress).filter(id => !original.progress[id])
  assert.ok(newlyIntroduced.every(id => lessonTwoBundle.entries.some(entry => entry.entryId === id)))
  assert.ok(state.session!.introducedEntryIds.length <= 5)
  state = transition(state, { type: 'select-lesson', lessonId: firstId }, courseBundle, NOW)
  validateState(state, courseBundle)
  assert.deepEqual(state.session, original.session)
  assert.equal(state.session!.draft, original.session!.draft)
  assert.deepEqual(state.session!.queue, original.session!.queue)
  assert.equal(state.session!.cursor, original.session!.cursor)
})

test('lesson-two reverse cards may review actual old-lesson evidence without changing the selected lesson', () => {
  let state = migrateState(baseline, courseBundle)
  const firstId = lessonOneBundle.lesson.lessonId, secondId = lessonTwoBundle.lesson.lessonId
  state = transition(state, { type: 'select-lesson', lessonId: secondId }, courseBundle, NOW)
  state = transition(state, { type: 'start-session', sessionId: 'second-with-old-reverse', seed: 75 }, courseBundle, NOW)
  validateState(state, courseBundle)
  const reverse = state.session!.queue.filter(task => task.kind === 'reverse-card')
  assert.ok(reverse.length > 0 && reverse.length <= 2)
  for (const task of reverse) {
    assert.equal(task.revealed, false)
    assert.ok(baseline.reverseProgress[task.entryId])
    assert.equal(courseBundle.entries.find(entry => entry.entryId === task.entryId)!.introducedInLessonId, firstId)
  }
  assert.equal(state.activeLessonId, secondId)
  assert.equal(state.session!.lessonId, secondId)
  assert.deepEqual(state.reverseReviews, baseline.reverseReviews, 'queue construction is not a self-assessment')
  assert.deepEqual(state.attempts, baseline.attempts)
})

test('an additive lesson keeps rejecting foreign versions and starts no repeated lesson-one identities', () => {
  const secondIds = new Set(lessonTwoBundle.entries.map(entry => entry.entryId))
  assert.ok(secondIds.size > 0)
  assert.equal(secondIds.size, lessonTwoBundle.entries.length)
  assert.ok(lessonOneBundle.entries.every(entry => !secondIds.has(entry.entryId)))
  for (const foreign of [
    { ...structuredClone(baseline), schemaVersion: 4 },
    { ...structuredClone(baseline), schemaVersion: 6 },
    { ...structuredClone(baseline), contentVersion: 'course-a1-lessons-01-04-v1' },
  ]) {
    const unchanged = structuredClone(foreign)
    assert.throws(() => migrateState(foreign, courseBundle), StorageError)
    assert.deepEqual(foreign, unchanged)
  }
  let fresh = createInitialState(courseBundle, 'Europe/Berlin')
  fresh = transition(fresh, { type: 'select-lesson', lessonId: lessonTwoBundle.lesson.lessonId }, courseBundle, NOW)
  fresh = transition(fresh, { type: 'start-session', sessionId: 'fresh-second-only', seed: 93 }, courseBundle, NOW)
  validateState(fresh, courseBundle)
  assert.equal(currentTask(fresh)!.kind, 'flashcard')
  assert.ok(Object.keys(fresh.progress).every(id => secondIds.has(id)), 'occurrences of earlier vocabulary do not fabricate new identities or progress')
})
